import {comparisonText,comparisonSentence} from './display.js';
import {describe,filterBuildings,isNumber,scenario,sortRows,csvText} from './analytics.js';
const asset=path=>new URL(path,import.meta.url).href;
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=(n,d=0)=>isNumber(n)?n.toLocaleString('en-US',{maximumFractionDigits:d,minimumFractionDigits:d}):'No data available';
let data,meta,peers,dictionary,campuses,relationships,state={type:'focus',min:'',max:'',zip:'',status:'',query:'',sort:'relative_to_peer',direction:'desc',page:0,fraction:.5,list:'energy'};
const main=$('#main');
function head(eyebrow,title,subtitle){return `<div class="page-head"><div><p class="eyebrow">${eyebrow}</p><h1>${title}</h1><p class="subtitle">${subtitle}</p></div><p class="period">${esc(meta.period_label)}</p></div>`}
function stats(){return `<div class="stats"><div class="stat"><span class="value">${fmt(meta.non_campus_n)}</span><span class="label">Non-campus buildings</span><small>Individual-building exploration population</small></div><div class="stat"><span class="value">${fmt(meta.energy_eligible_n)}</span><span class="label">Energy comparison inputs valid</span><small>${fmt(100*meta.energy_eligible_n/meta.non_campus_n,1)}% of ${fmt(meta.non_campus_n)} non-campus buildings</small></div><div class="stat"><span class="value">${fmt(meta.comparison_eligible_n)}</span><span class="label">Have a sufficient peer group</span><small>At least ${meta.minimum_peers} eligible peers of similar use and size</small></div><div class="stat"><span class="value">${fmt(meta.campus_summaries_n)}</span><span class="label">Campus reporting entities</span><small>Kept separate from building comparisons</small></div></div>`}
function distribution(rows){const groups=[...new Set(rows.map(r=>r.type))].map(type=>({type,...describe(rows.filter(r=>r.type===type))})).filter(x=>x.n).sort((a,b)=>b.n-a.n);if(!groups.length)return '<div class="empty">No data available for this selection.</div>';const scaleMax=Math.max(1,...groups.map(g=>g.max));return `<p class="note">Shared scale: 0–${fmt(scaleMax,1)} kBtu/ft²/year</p>`+groups.map(g=>`<div class="distribution-row"><div class="distribution-label"><span>${esc(g.type)}</span><strong>${fmt(g.median,1)}</strong></div><div class="track" role="img" aria-label="${esc(g.type)} median ${fmt(g.median,1)}, quartiles ${fmt(g.q1,1)} and ${fmt(g.q3,1)}, range ${fmt(g.min,1)} to ${fmt(g.max,1)}, n ${g.n}"><span class="whisker" style="left:${100*g.min/scaleMax}%;width:${100*(g.max-g.min)/scaleMax}%"></span><span class="box" style="left:${100*g.q1/scaleMax}%;width:${100*(g.q3-g.q1)/scaleMax}%"></span><span class="median" style="left:${100*g.median/scaleMax}%"></span></div><div class="distribution-n">n=${fmt(g.n)} · Middle 50%: ${fmt(g.q1,1)}–${fmt(g.q3,1)} · Full range: ${fmt(g.min,1)}–${fmt(g.max,1)}</div></div>`).join('')}
function renderPreview(){main.innerHTML=head('A closer look at the built environment','Boston Building Energy Explorer','Compare similar buildings and identify priorities for further investigation.')+stats()+`<div class="chips"><button class="chip active" data-preset="focus">Multifamily + Office</button><button class="chip" data-preset="all">All property types</button></div><div class="panel"><h2>Calculated Site EUI by property type</h2><p class="note">kBtu/ft²/year · Quality-eligible non-campus buildings in the current selection. Shared linear scale; median and middle 50% shown below.</p><div id="distribution">${distribution(filterBuildings(data,state))}</div></div><div class="callout">High energy intensity is a starting point for investigation. It does not establish poor management or achievable savings. Campus members are excluded from individual-building comparisons.</div>`;document.querySelectorAll('[data-preset]').forEach(b=>b.onclick=()=>{state.type=b.dataset.preset;$('#distribution').innerHTML=distribution(filterBuildings(data,state));document.querySelectorAll('[data-preset]').forEach(x=>x.classList.toggle('active',x===b))})}
let route='explore',visible=[],tableRows=[],scatterRows=[],pointIndex=0,methodState={scope:'non_campus',query:'',page:0};
const human=s=>s.replaceAll('_',' '), numberOrDash=(n,d=1)=>isNumber(n)?fmt(n,d):'—';
function statBlock(value,label,note){return `<div class="stat"><span class="value">${value}</span><span class="label">${label}</span><small>${note}</small></div>`}
function filters(){return `<aside class="filters" aria-label="Building filters"><div class="filter-head"><h3>Filter buildings</h3><button class="link-button" id="reset">Reset all</button></div><div><label for="type">Property type</label><select id="type"><option value="focus">Multifamily + Office</option><option value="all">All property types</option>${[...new Set(data.filter(r=>r.grain==='non_campus').map(r=>r.type))].sort().map(t=>`<option>${esc(t)}</option>`).join('')}</select></div><div><label>Floor area (ft²)</label><div class="range-fields"><input id="min" aria-label="Minimum floor area" type="number" min="0" placeholder="Min"><input id="max" aria-label="Maximum floor area" type="number" min="0" placeholder="Max"></div></div><div><label for="zip">ZIP code</label><select id="zip"><option value="">All ZIP codes</option>${[...new Set(data.map(r=>r.zip).filter(Boolean))].sort().map(z=>`<option>${esc(z)}</option>`).join('')}</select></div><div><label for="status">Reporting status</label><select id="status"><option value="">All reporting statuses</option>${[...new Set(data.map(r=>r.status))].sort().map(z=>`<option>${esc(z)}</option>`).join('')}</select></div><p class="hint"><strong>A fixed point of comparison.</strong><br>Filters change the buildings you see. Peer medians stay fixed to the eligible full disclosure population.</p><p class="hint">“In compliance” refers to reporting and verification, not emissions compliance. “state” is an unexplained source category.</p></aside>`}
function chips(){return `<div class="chips" aria-label="Quick property filters"><button class="chip" data-preset="focus">Multifamily + Office</button><button class="chip" data-preset="Multifamily Housing">Multifamily Housing</button><button class="chip" data-preset="Office">Office</button><button class="chip" data-preset="all">All property types</button></div>`}
function tableShell(){return `<section class="panel table-panel"><div class="table-tools"><div><h2 id="table-heading">Building comparison</h2><p class="note" id="table-scope"></p></div><input id="query" type="search" aria-label="Search buildings" placeholder="Search address, BERDO ID, or flag"></div><div class="table-wrap"><table><caption class="visually-hidden">Filtered buildings, calculated Site EUI and fixed peer benchmarks</caption><thead><tr>${[['id','Building / BERDO ID'],['area','Floor area ft²'],['calculated_eui','Calculated EUI ↕'],['peer_median','Typical similar building'],['relative_to_peer','Difference vs similar ↕'],['estimated_emissions_tonnes','Est. tCO₂e ↕'],['status','Review & status']].map(([key,label])=>`<th scope="col"><button data-sort="${key}">${label}</button></th>`).join('')}</tr></thead><tbody id="table-body"></tbody></table></div><div class="pagination"><span id="pagination-label"></span><div><button id="prev">← Previous</button><button id="next">Next →</button></div></div></section>`}
function explore(){main.innerHTML=head('Explore the disclosure','Full building analysis','Compare similar buildings and identify priorities for further investigation.')+stats()+chips()+`<div class="workspace">${filters()}<div><div class="result-line"><p id="filter-summary" aria-live="polite"></p><button id="export">↓ Export selection</button></div><div class="chart-grid"><section class="panel"><div class="panel-title"><h2>Energy intensity by use</h2><span class="eyebrow">01</span></div><p class="note">Calculated Site EUI · kBtu/ft²/year<br>Line: full range · Box: middle 50% · Mark: median</p><div id="distribution"></div><p class="note">All rows share the same linear scale. Different uses can have different operating needs.</p></section><section class="panel"><div class="panel-title"><h2>Size & energy intensity</h2><span class="eyebrow">02</span></div><div class="legend"><span><i class="swatch"></i>● Multifamily</span><span><i class="swatch office"></i>■ Office</span><span><i class="swatch other"></i>▲ Other</span></div><div id="scatter"></div><p id="scatter-note" class="note"></p><div id="point-info" class="tooltip" aria-live="polite">Hover over a building or select one to inspect its peer comparison. Keyboard: focus the plot, use arrow keys, then Enter.</div></section></div>${tableShell()}<div class="callout">Calculated Site EUI = total reported site energy ÷ reported floor area excluding parking. Missing values stay missing. The energy distribution uses records that pass energy checks; the table retains every selected record.</div></div></div>`;bindWorkspace();updateWorkspace()}
function priorities(){main.innerHTML=head('A starting point for action','Investigation priorities','Separate an energy question from a data question.')+`<div class="callout">Energy candidates exceed the upper quartile of their fixed property-type and size peer group (n ≥ ${meta.minimum_peers}). This is a transparent screening rule, not proof of inefficient operation. A separate emissions or water issue can still require review.</div>`+chips()+`<div class="workspace">${filters()}<div><div class="result-line"><p id="filter-summary" aria-live="polite"></p><button id="export">↓ Export current list</button></div><section class="scenario"><div><p class="eyebrow" style="color:#d9e8ce">Explore a benchmark scenario</p><h2>How far toward typical use?</h2><label for="closure">Move toward typical use by <output id="closure-label">50%</output></label><input id="closure" type="range" min="0" max="100" step="1" value="${state.fraction*100}"><p>0% = current use. 100% = the typical use of similar buildings.<br>Illustrative comparison only. Not verified engineering savings, emissions reductions, or financial returns.</p></div><div><p>Benchmark scenario energy difference</p><strong class="scenario-value" id="scenario-value"></strong><p id="scenario-population"></p><p class="note">Fixed reference: same primary property type and reported floor-area band; median Calculated Site EUI; at least ${meta.minimum_peers} eligible records.</p></div></section><details><summary>Scenario formula and assumptions</summary><p class="formula">max(0, Calculated Site EUI − peer median) × reported gross floor area × selected gap closure fraction</p><p class="note">The fraction is stored between 0 and 1. The scenario includes all currently filtered comparison-eligible non-campus buildings, including zero-gap buildings, independently of the list tab. Required energy inputs and checks must pass. Buildings without enough peers are excluded. Operations, mixed uses, occupancy and technical feasibility are not controlled.</p></details><div class="tab-buttons" role="group" aria-label="Priority list"><button id="energy-list">Energy-investigation candidates</button><button id="review-list">Data-quality review cases</button></div><label for="priority-sort" class="note">Sort the current list</label><select id="priority-sort"><option value="relative_to_peer">Energy use above similar buildings, highest first</option><option value="full_gap_kbtu">Benchmark scenario energy difference, largest first</option><option value="id">BERDO ID</option></select>${tableShell()}<p class="note">The lists can overlap where an unrelated emissions or water issue remains. No opaque composite score is used.</p></div></div>`;bindWorkspace();$('#closure').oninput=e=>{state.fraction=Number(e.target.value)/100;updateScenario()};$('#energy-list').onclick=()=>{state.list='energy';state.page=0;updateWorkspace()};$('#review-list').onclick=()=>{state.list='review';state.page=0;updateWorkspace()};$('#priority-sort').value=state.sort;$('#priority-sort').onchange=e=>{state.sort=e.target.value;state.direction=state.sort==='id'?'asc':'desc';state.page=0;updateWorkspace()};updateWorkspace()}
function bindWorkspace(){for(const key of ['type','min','max','zip','status','query']){const el=$('#'+key);el.value=state[key];el.addEventListener(el.tagName==='SELECT'?'change':'input',()=>{state[key]=el.value;state.page=0;updateWorkspace()})}$('#reset').onclick=()=>{Object.assign(state,{type:'focus',min:'',max:'',zip:'',status:'',query:'',page:0});for(const key of ['type','min','max','zip','status','query'])$('#'+key).value=state[key];updateWorkspace()};document.querySelectorAll('[data-preset]').forEach(b=>b.onclick=()=>{state.type=b.dataset.preset;state.page=0;$('#type').value=state.type;updateWorkspace()});document.querySelectorAll('[data-sort]').forEach(b=>b.onclick=()=>{state.direction=state.sort===b.dataset.sort&&state.direction==='desc'?'asc':'desc';state.sort=b.dataset.sort;state.page=0;updateWorkspace()});$('#prev').onclick=()=>{state.page--;updateTable()};$('#next').onclick=()=>{state.page++;updateTable()};$('#export').onclick=()=>downloadCsv(route==='priorities'?tableRows:visible,'boston-filtered-buildings.csv',route==='priorities'?state.fraction:undefined)}
function updateWorkspace(){clearExport();visible=filterBuildings(data,state);const eligible=visible.filter(r=>r.energy_eligible);const label=state.type==='focus'?'Multifamily Housing + Office':state.type==='all'?'All property types':state.type;$('#filter-summary').textContent=`${fmt(visible.length)} buildings · ${fmt(eligible.length)} energy-eligible · ${label}${state.min||state.max?' · '+(state.min||'0')+'–'+(state.max||'any')+' ft²':''}${state.zip?' · ZIP '+state.zip:''}${state.status?' · '+state.status:''}${state.query?' · Search: '+state.query:''}`;document.querySelectorAll('[data-preset]').forEach(b=>{b.classList.toggle('active',b.dataset.preset===state.type);b.setAttribute('aria-pressed',b.dataset.preset===state.type)});if(route==='explore'){$('#distribution').innerHTML=distribution(visible);renderScatter(visible);tableRows=visible}else{tableRows=visible.filter(r=>state.list==='energy'?r.investigation_candidate:r.review_required);$('#energy-list').classList.toggle('primary',state.list==='energy');$('#review-list').classList.toggle('primary',state.list==='review');$('#energy-list').setAttribute('aria-pressed',state.list==='energy');$('#review-list').setAttribute('aria-pressed',state.list==='review');updateScenario()}$('#table-heading').textContent=route==='explore'?'Building comparison':state.list==='energy'?'Energy-investigation candidates':'Data-quality review cases';$('#table-scope').textContent=`${fmt(tableRows.length)} records · EUI in kBtu/ft²/year · Estimated emissions in metric tons CO₂e. — means unavailable or ineligible.`;updateTable()}
function updateScenario(){clearExport();const s=scenario(visible,state.fraction);$('#closure-label').textContent=fmt(state.fraction*100)+'%';$('#scenario-value').textContent=s.kbtu===null?'No data available':fmt(s.kbtu/1e6,2)+' million kBtu';$('#scenario-population').textContent=`${fmt(s.n)} eligible of ${fmt(visible.length)} selected buildings; ${fmt(s.above)} above typical use for similar buildings. This moves ${fmt(state.fraction*100)}% of the way toward typical use, applied only to energy above that level.`}
function quality(r){const issues=r.quality_flags.filter(f=>f!=='emissions_components_incomplete');if(r.grain==='campus_member')return '<span class="badge muted">Campus member</span>';if(r.grain==='campus_summary')return '<span class="badge muted">Campus summary</span>';if(!r.energy_eligible)return `<span class="badge warn">Energy input review</span><span class="minor">${esc(human(r.energy_exclusions[0]||'Review inputs'))}</span>`;if(r.review_required)return `<span class="badge warn">Other data review</span><span class="minor">${esc(human(issues[0]||'Review inputs'))}</span>`;return `<span class="badge">Energy data checks passed</span>`}
function rowsHtml(rows){return rows.map(r=>`<tr><td><button class="id-link" data-detail="${esc(r.id)}">${esc(r.id)}</button><span class="minor">${esc(r.address)}</span><span class="minor">${esc(r.type)}</span></td><td class="numeric">${numberOrDash(r.area,0)}</td><td class="numeric">${numberOrDash(r.calculated_eui)}${!r.energy_eligible?'<span class="minor">Energy comparison unavailable</span>':''}</td><td class="numeric">${r.comparison_eligible?fmt(r.peer_median,1):'—'}<span class="minor">${r.energy_eligible&&r.peer_n<meta.minimum_peers?'Insufficient peer sample':r.comparison_eligible?'n = '+fmt(r.peer_n):'Not eligible'}</span></td><td class="numeric">${r.relative_to_peer!==null?comparisonText(r.relative_to_peer):'—'}</td><td class="numeric">${numberOrDash(r.estimated_emissions_tonnes,1)}${r.emissions_exclusions.length?'<span class="minor">Review estimate</span>':''}</td><td>${quality(r)}<span class="minor">${esc(r.status)}</span></td></tr>`).join('')}
function bindDetails(){document.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>openDetail(b.dataset.detail))}
function updateTable(){const ordered=sortRows(tableRows,state.sort,state.direction);state.page=Math.max(0,Math.min(state.page,Math.max(0,Math.ceil(ordered.length/20)-1)));const start=state.page*20;$('#table-body').innerHTML=ordered.length?rowsHtml(ordered.slice(start,start+20)):'<tr><td colspan="7" class="empty">No data available. Try a broader selection or reset the filters.</td></tr>';$('#pagination-label').textContent=ordered.length?`${start+1}–${Math.min(start+20,ordered.length)} of ${fmt(ordered.length)} · Sorted by ${{relative_to_peer:'difference from similar buildings',full_gap_kbtu:'scenario energy difference',calculated_eui:'energy use per ft²',estimated_emissions_tonnes:'estimated emissions'}[state.sort]||human(state.sort)} · ${state.direction==='desc'?'highest first':'lowest first'}`:'0 records';$('#prev').disabled=state.page===0;$('#next').disabled=start+20>=ordered.length;document.querySelectorAll('[data-sort]').forEach(b=>b.parentElement.setAttribute('aria-sort',state.sort===b.dataset.sort?(state.direction==='asc'?'ascending':'descending'):'none'));bindDetails()}
function renderScatter(rows){scatterRows=rows.filter(r=>r.energy_eligible&&r.area>0&&r.calculated_eui>0);pointIndex=0;$('#scatter-note').textContent=`${fmt(scatterRows.length)} plotted of ${fmt(rows.length)} selected. ${fmt(rows.length-scatterRows.length)} not plotted: ${fmt(rows.filter(r=>!r.energy_eligible).length)} fail energy eligibility; ${fmt(rows.filter(r=>r.energy_eligible&&!(r.area>0&&r.calculated_eui>0)).length)} have nonpositive axes. Both axes logarithmic. Table provides the text alternative.`;if(!scatterRows.length){$('#scatter').innerHTML='<div class="empty">No data available for positive, energy-eligible axes.</div>';return}const W=550,H=290,L=62,R=18,T=18,B=49;const xmin=Math.floor(Math.log10(Math.min(...scatterRows.map(r=>r.area)))),xmax=Math.ceil(Math.log10(Math.max(...scatterRows.map(r=>r.area)))),ymin=Math.floor(Math.log10(Math.min(...scatterRows.map(r=>r.calculated_eui)))),ymax=Math.ceil(Math.log10(Math.max(...scatterRows.map(r=>r.calculated_eui))));const x=v=>L+(Math.log10(v)-xmin)/(xmax-xmin||1)*(W-L-R),y=v=>H-B-(Math.log10(v)-ymin)/(ymax-ymin||1)*(H-T-B);let axes='';for(let i=xmin;i<=xmax;i++)axes+=`<line x1="${x(10**i)}" x2="${x(10**i)}" y1="${T}" y2="${H-B}" stroke="#e4e9df"/><text x="${x(10**i)}" y="${H-B+20}" text-anchor="middle" fill="#637064" font-size="11">${10**i>=1000?fmt(10**i/1000)+'k':fmt(10**i)}</text>`;for(let i=ymin;i<=ymax;i++)axes+=`<line x1="${L}" x2="${W-R}" y1="${y(10**i)}" y2="${y(10**i)}" stroke="#e4e9df"/><text x="${L-9}" y="${y(10**i)+4}" text-anchor="end" fill="#637064" font-size="11">${fmt(10**i,10**i<1?Math.abs(i):0)}</text>`;$('#scatter').innerHTML=`<svg class="chart" viewBox="0 0 ${W} ${H}" tabindex="0" role="group" aria-label="Building size versus calculated Site EUI. Use arrow keys to explore buildings and Enter for details.">${axes}<text x="${W/2}" y="${H-4}" text-anchor="middle" font-size="12" fill="#526454">Reported floor area (ft², log scale)</text><text transform="translate(14 ${H/2}) rotate(-90)" text-anchor="middle" font-size="12" fill="#526454">Calculated Site EUI (log scale)</text>${scatterRows.map((r,i)=>{const px=x(r.area),py=y(r.calculated_eui),attrs=`data-point="${i}" fill="${r.type==='Office'?'#748bb7':r.type==='Multifamily Housing'?'#164e3e':'#929c90'}" fill-opacity=".5" stroke="white" stroke-width=".4"`;const title=`<title>${esc(r.id)} · ${esc(r.type)} · ${fmt(r.area)} ft² · EUI ${fmt(r.calculated_eui,1)}</title>`;return r.type==='Office'?`<rect x="${px-3}" y="${py-3}" width="6" height="6" ${attrs}>${title}</rect>`:r.type==='Multifamily Housing'?`<circle cx="${px}" cy="${py}" r="3.3" ${attrs}>${title}</circle>`:`<path d="M ${px} ${py-4} l 4 7 h -8 Z" ${attrs}>${title}</path>`}).join('')}</svg>`;$('#scatter svg').onpointerover=e=>{const n=e.target.closest('[data-point]');if(n)showPoint(Number(n.dataset.point))};$('#scatter svg').onclick=e=>{const n=e.target.closest('[data-point]');if(n)openDetail(scatterRows[Number(n.dataset.point)].id)};$('#scatter svg').onfocus=()=>showPoint(pointIndex);$('#scatter svg').onkeydown=e=>{if(['ArrowRight','ArrowDown','ArrowLeft','ArrowUp'].includes(e.key)){e.preventDefault();pointIndex=(pointIndex+(['ArrowRight','ArrowDown'].includes(e.key)?1:-1)+scatterRows.length)%scatterRows.length;showPoint(pointIndex)}else if(e.key==='Enter')openDetail(scatterRows[pointIndex].id)}}
function showPoint(i){const r=scatterRows[i];$('#point-info').textContent=`${r.id} · ${r.address} · ${fmt(r.area)} ft² · Calculated EUI ${fmt(r.calculated_eui,1)}. ${r.comparison_eligible?'Typical similar building: '+fmt(r.peer_median,1)+' kBtu/ft²/year ('+r.peer_n+' buildings). '+comparisonSentence(r.relative_to_peer)+'.':'Insufficient peer sample (n='+r.peer_n+').'}`}
function openDetail(id){const r=[...data,...campuses].find(r=>r.id===id);if(!r)return;const cells=[['Calculated Site EUI',numberOrDash(r.calculated_eui)+' kBtu/ft²/year'],['Reported Site EUI',numberOrDash(r.reported_eui)+' kBtu/ft²/year'],['Reported floor area',numberOrDash(r.area,0)+' ft²'],['Estimated emissions',numberOrDash(r.estimated_emissions_tonnes)+' tCO₂e'],['Emissions floor area',numberOrDash(r.emissions_area,0)+' ft²'],['Reporting status',esc(r.status)]];$('#detail-body').innerHTML=`<p class="eyebrow">${esc(human(r.grain))} · ${esc(r.id)}</p><h2>${esc(r.address)}</h2><p class="note">${esc(r.address_source)}${r.address_source==='Parcel address fallback'?' · Not a verified entrance location':''} · ZIP ${esc(r.zip||'not provided')} · ${esc(r.type)}</p><div class="detail-grid">${cells.map(([l,v])=>`<div><strong>${v}</strong><small>${l}</small></div>`).join('')}</div>${r.grain==='campus_member'?`<div class="callout">Shared metering: member of ${r.campus_ids.join(', ')}. Not ranked as an independently metered whole building.</div>`:r.comparison_eligible?`<h3>Fixed peer comparison</h3><p>${esc(r.type)} · ${esc(r.area_band)} ft² · n=${r.peer_n}</p><div class="callout">Median <strong>${fmt(r.peer_median,1)}</strong> · Quartiles ${fmt(r.peer_q1,1)}–${fmt(r.peer_q3,1)} kBtu/ft²/year.<br>This building: <strong>${comparisonSentence(r.relative_to_peer)}</strong>, at the ${fmt(r.peer_percentile)}th percentile (empirical share at or below its EUI, including itself).</div><p>Benchmark scenario energy difference at ${fmt(state.fraction*100)}% closure: <strong>${fmt(r.full_gap_kbtu*state.fraction)} kBtu</strong>. Illustrative only; no engineering savings claim.</p>`:`<div class="callout warn">${r.energy_eligible?'Insufficient peer sample (n='+r.peer_n+').':'Excluded from individual-building peer comparisons.'}</div>`}<h3>Quality and interpretation</h3><p class="note">Reported-to-calculated EUI difference: ${numberOrDash(r.eui_difference,3)} kBtu/ft². Project review threshold: absolute difference &gt; 0.11.</p><ul>${r.quality_flags.length?r.quality_flags.map(f=>`<li>${esc(human(f))}</li>`).join(''):'<li>No project quality flags.</li>'}</ul><p class="note">Missing emissions components are not assumed zero. Their observed sum is ${numberOrDash(r.emissions_component_sum,3)} kgCO₂e; total minus observed sum is ${numberOrDash(r.emissions_difference,3)} kgCO₂e. Estimated emissions do not determine final BERDO compliance.</p><p class="note">Emissions intensity: ${numberOrDash(r.emissions_intensity,2)} kgCO₂e/ft²/year, using the emissions floor area that includes enclosed parking. Water intensity: ${numberOrDash(r.water_intensity,2)} gallons/ft²/year; a separate review metric.</p><h3>Record provenance</h3><p class="note">Selected source: ${esc(r.source_sheet)}, Excel row ${r.source_row}.<br>All appearances: ${r.source_locations.map(s=>esc(s.sheet)+' row '+s.row).join('; ')}.<br>Public downloads preserve safe original field values; owner names and free-text notes are omitted.</p>`;$('#detail').showModal()}
$('#close-detail').onclick=()=>$('#detail').close();
let exportUrl;
function clearExport(){document.querySelector("#export-ready")?.remove();if(exportUrl){URL.revokeObjectURL(exportUrl);exportUrl=null}}
function downloadCsv(rows,name,fraction){if(exportUrl)URL.revokeObjectURL(exportUrl);exportUrl=URL.createObjectURL(new Blob([csvText(rows,fraction)],{type:'text/csv;charset=utf-8'}));let ready=$('#export-ready');if(!ready){ready=document.createElement('div');ready.id='export-ready';ready.className='callout';ready.setAttribute('role','status');const trigger=route==='methods'?$('#data-export'):$('#export');trigger.parentElement.insertAdjacentElement('afterend',ready)}ready.innerHTML=`<strong>${fmt(rows.length)} records prepared.</strong> <a id="download-csv" href="${exportUrl}" download="${name}">Download CSV ↓</a> <span class="note">Includes the current selection, provenance and quality flags.</span>`;$('#download-csv').click()}
function overview(){const mf=meta.type_stats.find(t=>t.type==='Multifamily Housing'),of=meta.type_stats.find(t=>t.type==='Office');main.innerHTML=head('Overview','A clearer starting point<br>for building energy decisions.','For Boston energy planners, building managers, and community sustainability organizations.')+`<p class="prose">Among buildings with similar uses and sizes, which warrant further energy-efficiency investigation, and which records require data-quality review first?</p>`+stats()+`<a class="button primary" href="#explore">Explore buildings →</a><section class="section"><div class="section-title"><h2>What the disclosure tells us</h2><p>One release, with explicit coverage and a fixed comparison population. Descriptive evidence supports a next question, not a causal conclusion.</p></div><div class="three-col"><article class="editorial"><span class="number">01</span><h3>${fmt(meta.energy_eligible_n/meta.non_campus_n*100,1)}% pass energy input checks</h3><p>${fmt(meta.energy_eligible_n)} of ${fmt(meta.non_campus_n)} non-campus buildings are eligible for the EUI reference population. ${fmt(meta.non_campus_n-meta.energy_eligible_n)} are excluded. Missing energy data is the largest exclusion category (${fmt(meta.energy_exclusion_counts.site_energy_missing)} records; reasons overlap).</p></article><article class="editorial"><span class="number">02</span><h3>Similar uses still show a wide spread</h3><p>Eligible multifamily EUI has a median of ${fmt(mf.median,1)} and an interquartile range of ${fmt(mf.q1,1)}–${fmt(mf.q3,1)} (n=${fmt(mf.n)}). Office: median ${fmt(of.median,1)}, range between quartiles ${fmt(of.q1,1)}–${fmt(of.q3,1)} (n=${fmt(of.n)}), in kBtu/ft²/year. These category comparisons are descriptive.</p></article><article class="editorial"><span class="number">03</span><h3>${fmt(meta.investigation_candidates_n)} buildings warrant a closer look</h3><p>These eligible buildings exceed their peer group's upper quartile, among ${fmt(meta.comparison_eligible_n)} with sufficient peers. Operating hours, mixed uses and occupancy could explain part of each gap.</p></article></div></section><section class="section two-col"><article class="editorial"><h2>Investigate the operating context</h2><p>${fmt(meta.investigation_candidates_n)} upper-quartile candidates provide a manageable starting list. Request operating schedules, meter boundaries, occupancy and equipment information before commissioning an energy audit. The disclosure cannot quantify achievable savings or retrofit economics.</p><a href="#priorities">View energy-investigation candidates →</a></article><article class="editorial"><h2>Resolve missing and inconsistent inputs</h2><p>${fmt(meta.review_cases_n)} non-campus records need data review across the project checks. Verify missing inputs and the negative electricity values at BERDO IDs 102879 and 105219 against original submissions. Fixing a record can change its comparison eligibility; missingness alone does not prove poor management.</p><a href="#priorities" id="go-review">View data-quality cases →</a></article></section><section class="section"><h2>Know which population you are using</h2><div class="table-wrap"><table><thead><tr><th>Population</th><th>Count</th><th>Use</th></tr></thead><tbody><tr><td>All unique building IDs</td><td>${fmt(meta.buildings_n)}</td><td>Building coverage, reporting status and relationships</td></tr><tr><td>Non-campus buildings</td><td>${fmt(meta.non_campus_n)}</td><td>Exploration and eligible individual-building comparisons</td></tr><tr><td>Campus members</td><td>${fmt(meta.campus_members_n)}</td><td>Relationships only; excluded from individual rankings</td></tr><tr><td>Non-campus buildings + one summary per campus</td><td>${fmt(meta.aggregate_entities_n)} entities</td><td>Deduplicated reported energy and emissions aggregates</td></tr></tbody></table></div><p class="note">The source contains ${fmt(meta.relationships_n)} campus-member references. Two reference IDs absent from the building records: ${meta.relationship_issues.map(r=>r.id+' in '+r.summary_campuses.join(', ')).join('; ')}. They are not invented as additional building records.</p></section><section class="section panel"><p class="eyebrow">Reported values within this disclosure dataset</p><h2>Buildings and campuses, counted once</h2><p>These aggregates include ${fmt(meta.non_campus_n)} non-campus buildings and ${meta.campus_summaries_n} campus reporting entities. They are not complete citywide totals. Campus values are not allocated to a member's ZIP code or category.</p><div class="stats">${Object.entries(meta.aggregates).map(([k,v])=>statBlock(fmt(v.reported_sum/(k==='site_energy'?1e9:1e3),k==='site_energy'?2:0),k==='site_energy'?'Billion kBtu, reported site energy':'Metric tons CO₂e, estimated emissions',`${fmt(v.numeric_n)} numeric of ${fmt(v.entities)} entities. Original reported values; negatives included.`)).join('')}</div><details><summary>Quality-screened totals and inclusion rules</summary><p>Site energy: ${fmt(meta.aggregates.site_energy.screened_sum/1e9,2)} billion kBtu across ${fmt(meta.aggregates.site_energy.screened_n)} entities with numeric nonnegative energy and all project energy checks passed. Estimated emissions: ${fmt(meta.aggregates.estimated_emissions_kg.screened_sum/1000)} tCO₂e across ${fmt(meta.aggregates.estimated_emissions_kg.screened_n)} entities without project emissions issues. Missing components remain unknown, even when the observed sum agrees.</p></details></section>`;$('#go-review').onclick=()=>state.list='review'}
function downloadLink(href,title,desc){return `<a class="download" href="${asset(href)}"${/\.(csv|json|pdf|zip|md|gz)$/.test(href)?' download':''}><strong>${title} ↗</strong><span>${desc}</span></a>`}
function methods(){main.innerHTML=head('Data & methods','The evidence behind the explorer.','Trace the records, reproduce the analysis, and understand its limits.')+`<div class="downloads">${downloadLink('data/buildings.csv','Building analysis dataset · CSV',`${fmt(meta.buildings_n)} unique building IDs. Includes ${fmt(meta.campus_members_n)} campus members for relationships only. Filter grain=non_campus for independent buildings.`)}${downloadLink('data/campus-summaries.csv','Campus summaries · CSV',`${meta.campus_summaries_n} unique campus records. Never add these to their member buildings.`)}${downloadLink('data/aggregate-entities.csv','Aggregate population · CSV',`${fmt(meta.aggregate_entities_n)} entities: non-campus buildings plus campus summaries; excludes campus members.`)}${downloadLink('data/campus-relationships.csv','Campus relationships · CSV',`${meta.relationships_n} campus/member references, including two missing building records. Not an energy fact table.`)}${downloadLink('data/peer-benchmarks.csv','Fixed peer benchmarks · CSV','Property type and size band, n, quartiles, median and comparison availability.')}${downloadLink('data/source-records.json.gz','Safe original values & provenance · compressed JSON','All source appearances, original field values, Excel row, headers, cell formats and normalized identifiers. Owner names and free-text notes omitted.')}${downloadLink('methodology.html','One-page data & methodology note','Readable web version with the same content as the printable one-page PDF.')}${downloadLink('deliverables/methodology.pdf','Printable methodology · PDF','Verified one-page note with source, scope, calculations and limitations.')}${downloadLink('walkthrough.html','Five-minute operation video','Watch the actual website demonstration with English captions. MP4 with English AI narration, chapter navigation and speaking outline included.')}${downloadLink('presentation.html','Presentation pages & outline','Companion presentation pages and the original five-minute English speaking outline.')}${downloadLink('reflection.html','Short reflection','What a single disclosure release supports, and what it cannot prove.')}${downloadLink('deliverables/project-source.zip','Website code & workflow · ZIP','Current website interface, shared analysis, processing scripts, final narrated video and README. Original workbook is obtained separately from the official source.')}</div><div id="github-status" class="callout">The complete source package is available above; repository delivery status is listed below.</div><section class="section two-col"><div><h2>Source & reporting period</h2><p><a href="${meta.source_url}" target="_blank" rel="noreferrer">Analyze Boston: 2025 Reported Energy and Water Metrics ↗</a><br><a href="${meta.official_context_url}" target="_blank" rel="noreferrer">Boston BERDO publication and reporting information ↗</a></p><p>${esc(meta.period_label)} ${esc(meta.year_evidence)}</p><p class="note">Official resource page: created ${meta.official_resource_created}; last updated ${meta.official_resource_updated}. These dates do not independently establish the local file's revision or energy-use year. Original download date: unknown. Processing date: ${meta.processed_at.slice(0,10)} (UTC).</p></div><div><h2>Coverage of non-campus buildings</h2><div class="table-wrap"><table><thead><tr><th>Metric</th><th>Population</th><th>Numeric</th><th>Eligible</th></tr></thead><tbody>${Object.entries(meta.coverage).map(([k,v])=>`<tr><td>${human(k)}</td><td>${fmt(v.population_n)}</td><td>${fmt(v.numeric_n)}<br>${fmt(v.numeric_coverage_pct,1)}%</td><td>${fmt(v.eligible_n)}</td></tr>`).join('')}</tbody></table></div><p class="note">Coverage denominator = all ${fmt(meta.non_campus_n)} non-campus records. Eligibility depends on the metric; numeric availability does not establish validity. Peer comparison also requires n ≥ ${meta.minimum_peers}.</p></div></section><section class="prose"><details><summary>Campus deduplication and source selection</summary><p>Headers identify sections; six-digit building IDs and C-prefixed campus IDs identify record grain. The main sheet's appended campus summaries reuse its building layout with the first two fields repurposed. The campus sheet uses its own summary and repeated member headers. ${fmt(meta.duplicate_records_removed)} duplicate appearances are removed, leaving ${fmt(meta.buildings_n)} buildings and ${meta.campus_summaries_n} campus summaries.</p><p>For duplicate campus summaries and members, “Data Disclosure - Campuses” is preferred. Non-campus records come from “Data Disclosure”. ${meta.conflict_field_count} conflicting shared field values were found after numeric normalization. Original representations and all source locations are retained. The Summary's claim that campus records were removed from the main sheet is contradicted by the actual file.</p><p>The campus lists reference ${meta.relationships_n} members, but only ${meta.campus_members_n} have building records. ${meta.relationship_issues.map(r=>r.id+' ('+r.summary_campuses.join(', ')+')').join(' and ')} are missing. Existing member-to-campus links agree. Campus members never enter peer rankings, scenarios or campus-inclusive sums.</p></details><details><summary>Cleaning and metric-specific eligibility</summary><p>Nulls, blank cells and #N/A remain missing. Explicit “not applicable”, unparseable text, genuine zeros, negative values and numeric text have separate value states in the CSV. Numeric text is parsed without overwriting raw values. IDs remain strings; leading zeros are restored only from verified all-zero Excel number formats (ZIP: 00000; parcel: 0000000000). Source ZIP errors are not silently corrected. Parcel Address is a labeled display fallback, not a verified entrance.</p><p>Calculated Site EUI = total site energy (kBtu) ÷ Reported Gross Floor Area (ft²), which excludes parking. Negative energy and nonpositive area do not produce an analytical EUI. Reported EUI remains separate. Absolute disagreement greater than 0.11 kBtu/ft² is a project consistency threshold, not an official standard. Missing reconciliation values, negative or unparseable energy components, missing type, relevant duplicate conflicts and unresolved energy discrepancies exclude a record from energy peers, rankings and scenarios.</p><p>An energy component exceeding the total by more than max(1 kBtu, 0.01% of total) also triggers review. For this lower-bound check only, electricity converts at 3.412141633 kBtu/kWh. The source dictionary says electricity already includes onsite renewable electricity; the two are never added. No fuel-composition chart or imputation of absent components is used.</p><p>Emissions checks compare estimated total to the sum of observed numeric emissions components, with a rounding tolerance of max(0.01 kgCO₂e, one millionth of the absolute total). This does not assert missing components are zero. All records have incomplete component coverage; agreement of observed values is only a partial reconciliation. Negative totals/components or a mismatch require emissions review, separately from energy eligibility.</p><p>Water intensity above 1,000 gallons/ft²/year is a project review flag, not a deletion rule or engineering limit. Large energy values remain eligible if checks pass. Missing ENERGY STAR scores are not classified as reporting failures because score applicability varies by property type.</p><p>Estimated emissions intensity uses BERDO Emissions Gross Floor Area, including enclosed parking. Kilograms convert to metric tons by dividing by 1,000. These estimates do not establish final emissions compliance.</p></details><details><summary>Exclusion counts and known anomalies</summary><div class="table-wrap"><table><thead><tr><th>Energy exclusion reason</th><th>Non-campus records</th></tr></thead><tbody>${Object.entries(meta.energy_exclusion_counts).map(([k,v])=>`<tr><td>${human(k)}</td><td>${fmt(v)}</td></tr>`).join('')}</tbody></table></div><p>Reasons overlap. ${fmt(meta.non_campus_n-meta.energy_eligible_n)} distinct records fail at least one energy check. BERDO 102879 has negative site energy, electricity, reported EUI and estimated emissions. BERDO 105219 has negative electricity. ${meta.quality_flag_counts.water_intensity_gt_1000} non-campus records exceed the water review threshold; ${meta.quality_flag_counts.emissions_component_sum_difference} have an observed emissions-component sum mismatch.</p></details><details><summary>Peer groups, ranks and scenarios</summary><p>Fixed reference population: all ${fmt(meta.energy_eligible_n)} eligible non-campus buildings in this release. Groups match Largest Property Type and reported area bands: ${meta.area_bands.join('; ')} ft². The observed positive floor-area distribution (n=${fmt(meta.area_distribution.n)}) has quartiles ${fmt(meta.area_distribution.q1)} and ${fmt(meta.area_distribution.q3)} ft² and median ${fmt(meta.area_distribution.median)}. Round band boundaries separate small, medium and large buildings; they are project definitions, not official classifications.</p><p>A minimum of ${meta.minimum_peers} eligible records is a display rule, not proof of statistical significance or representativeness. Quartiles use linear interpolation at (n−1)×p. A building is an investigation candidate when its Calculated Site EUI exceeds the eligible peer group's 75th percentile. Its EUI/median ratio and empirical percentile are descriptive; the reference population includes the building itself.</p><p>Filters never recalculate the stored benchmark. “Insufficient peer sample” means the building passes energy checks but its group has fewer than ${meta.minimum_peers} records. Such records remain visible without a comparison or scenario.</p><p class="formula">Benchmark scenario energy difference = max(0, calculated EUI − peer median EUI) × reported floor area × closure fraction</p><p>The fraction ranges from 0 to 1, default 0.5. Only comparison-eligible non-campus buildings enter the calculation. A zero-gap building contributes a genuine zero. If no eligible records exist, the output is “No data available”. This is an illustrative benchmark comparison, not an engineering savings estimate.</p></details><details><summary>Bias, uncertainty and interpretation</summary><p>Missingness, reporting quality and sample selection affect interpretation. Buildings with usable data may differ systematically from those without it. Matching property type and size does not fully control operational differences, mixed uses, operating hours or occupancy. Cross-type EUI comparisons do not establish inherent inefficiency.</p><p>A single release cannot establish trends or policy effects. Correlation does not identify causal effects of equipment or energy measures. Age, operating hours, occupancy, equipment efficiency, retrofit costs and energy prices are unavailable or insufficient. The explorer cannot produce verified retrofit payback, engineering savings or final emissions compliance determinations.</p></details></section><section class="section"><h2>Search the analysis data</h2><div class="table-tools"><label>Record population<select id="data-scope"><option value="non_campus">Non-campus buildings</option><option value="campus_member">Campus members (relationships only)</option><option value="campus_summary">Campus summaries</option><option value="all">All records (do not sum)</option></select></label><input id="data-search" aria-label="Search analysis data" type="search" placeholder="Search ID, address, campus or quality flag"><button id="data-export">↓ Export current data view</button></div><div class="table-wrap"><table><thead><tr><th>ID / address / type</th><th>Floor area ft²</th><th>Calculated EUI</th><th>Typical similar building</th><th>Difference vs similar</th><th>Est. tCO₂e</th><th>Review & status</th></tr></thead><tbody id="data-body"></tbody></table></div><div class="pagination"><span id="data-count"></span><div><button id="data-prev">← Previous</button><button id="data-next">Next →</button></div></div></section><section class="section"><h2>Data dictionary</h2><p class="note">Original field definitions from the supplied workbook, followed by project analysis fields. Source terminology is preserved; the project applies additional interpretation limits above.</p><input id="dictionary-search" type="search" aria-label="Search data dictionary" placeholder="Find a field or definition"><div id="dictionary-results"></div></section>`;$('#data-scope').value=methodState.scope;$('#data-search').value=methodState.query;$('#data-scope').onchange=e=>{methodState.scope=e.target.value;methodState.page=0;renderDataTable()};$('#data-search').oninput=e=>{methodState.query=e.target.value;methodState.page=0;renderDataTable()};$('#data-prev').onclick=()=>{methodState.page--;renderDataTable()};$('#data-next').onclick=()=>{methodState.page++;renderDataTable()};$('#data-export').onclick=()=>downloadCsv(methodRows(),'boston-analysis-view.csv');$('#dictionary-search').oninput=renderDictionary;renderDataTable();renderDictionary();fetch(asset('data/delivery.json')).then(r=>r.ok?r.json():null).then(d=>{if(d?.github_url&&$('#github-status'))$('#github-status').innerHTML=`GitHub repository: <a href="${esc(d.github_url)}">${esc(d.github_url)}</a>`}).catch(()=>{})}
function methodRows(){return [...data,...campuses].filter(r=>(methodState.scope==='all'||r.grain===methodState.scope)&&(!methodState.query||[r.id,r.address,r.type,...r.campus_ids,...r.quality_flags].join(' ').toLowerCase().includes(methodState.query.toLowerCase())))}
function renderDataTable(){clearExport();const rows=methodRows(),start=methodState.page*20;$('#data-body').innerHTML=rows.length?rowsHtml(rows.slice(start,start+20)):'<tr><td colspan="7" class="empty">No data available for this search.</td></tr>';$('#data-count').textContent=rows.length?`${start+1}–${Math.min(start+20,rows.length)} of ${fmt(rows.length)} records. Mixed grains must not be summed.`:'0 records';$('#data-prev').disabled=methodState.page===0;$('#data-next').disabled=start+20>=rows.length;bindDetails()}
const analyticalDictionary=[['id / grain / campus_ids','Identifier strings; grain is non_campus, campus_member or campus_summary. Campus IDs link members to summaries.'],['area / site_energy','Reported gross floor area excluding parking (ft²); reported total site energy (kBtu/year).'],['calculated_eui / reported_eui / eui_difference','Calculated Site EUI (kBtu/ft²/year), original reported EUI, and calculated minus reported. Negative energy or nonpositive area gives no calculated EUI.'],['peer_n / peer_median / peer_q1 / peer_q3','Fixed eligible reference group sample size and EUI distribution (kBtu/ft²/year). Group is primary type × area band.'],['relative_to_peer / peer_percentile','Calculated EUI divided by peer median (unitless), and percent of eligible peers at or below the building (0–100). Only comparison-eligible buildings receive them.'],['full_gap_kbtu / scenario_gap_kbtu','100% closure energy difference (kBtu); current export scenario multiplies by selected_gap_closure_fraction (0–1). Null if ineligible.'],['energy_eligible / comparison_eligible / investigation_candidate','Passes energy checks; additionally sufficient peer sample; additionally above peer 75th percentile. Boolean fields.'],['estimated_emissions_kg / estimated_emissions_tonnes / emissions_intensity','Estimated emissions in kgCO₂e and tCO₂e (kg/1,000); intensity in kgCO₂e/ft²/year using emissions_area including enclosed parking.'],['emissions_component_sum / emissions_difference / emissions_components_complete','Sum of observed numeric emissions components and total minus that sum (kgCO₂e). Missing components are not treated as zero; complete records require every component numeric.'],['quality_flags / energy_exclusions / emissions_exclusions / review_required','Named review issues, metric-specific exclusion lists and whether an actionable review exists. Component incompleteness alone is informational.'],['source_sheet / source_row / source_locations / raw_values / value_states','Selected worksheet and one-based Excel row; every duplicate location; safe original values and numeric classification. Owner names and free-text notes excluded.'],['zip / parcel_id / address_source','String identifiers use verified cell number formats for leading zeros. Address source explicitly distinguishes a parcel fallback.'],['status','Source reporting and verification category. Does not establish emissions compliance. The source value state is unexplained.']];
function renderDictionary(){const q=$('#dictionary-search').value.toLowerCase();const entries=[...analyticalDictionary.map(([field,definition])=>({field,definition,source:'Project analysis'})),...dictionary].filter(d=>(d.field+' '+d.definition).toLowerCase().includes(q));$('#dictionary-results').innerHTML=entries.length?entries.map(d=>`<details><summary>${esc(d.field)}</summary><p>${esc(d.definition)}</p><p class="note">${esc(d.source)}${d.excel_row?' · Excel row '+d.excel_row:''}</p></details>`).join(''):'<p class="empty">No matching fields.</p>'}
function render(){route=location.hash.slice(1)||'explore';document.body.dataset.analysisRoute=route;if(!['explore','overview','priorities','methods'].includes(route))route='explore';document.querySelectorAll('nav a').forEach(a=>{if(a.hash==='#'+route)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});({explore,overview,priorities,methods})[route]();document.title=(route==='explore'?'':route[0].toUpperCase()+route.slice(1)+' · ')+'Boston Building Energy Explorer'}
window.addEventListener('hashchange',()=>{if(data){render();window.scrollTo(0,0)}});
function registerTools(){if(!document.modelContext?.registerTool)return;const controller=new AbortController();try{Promise.resolve(document.modelContext.registerTool({name:'filter_buildings',description:'Update the visible building filters and return matching counts. Reference peer benchmarks remain fixed.',inputSchema:{type:'object',properties:{property_type:{type:'string'},zip:{type:'string'},query:{type:'string'}},additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute(input){if(!input||typeof input!=='object'||Object.keys(input).some(k=>!['property_type','zip','query'].includes(k))||Object.values(input).some(v=>typeof v!=='string'))throw Error('Expected string filter fields');if(input.property_type&&!['all','focus',...new Set(data.map(r=>r.type))].includes(input.property_type))throw Error('Unknown property type');Object.assign(state,{type:input.property_type||state.type,zip:input.zip??state.zip,query:input.query??state.query,page:0});location.hash='explore';render();return {matching:visible.length,energy_eligible:visible.filter(r=>r.energy_eligible).length,benchmark:'Fixed full-disclosure peer population'}}},{signal:controller.signal})).catch(()=>{});window.addEventListener('pagehide',()=>controller.abort(),{once:true})}catch{}}
Promise.all(['buildings','metadata','peers','dictionary','campuses','relationships'].map(f=>fetch(asset(`data/${f}.json`)).then(r=>{if(!r.ok)throw Error('Data request failed');return r.json()}))).then(all=>{[data,meta,peers,dictionary,campuses,relationships]=all;const params=new URLSearchParams(location.search);if(['all','focus',...new Set(data.map(r=>r.type))].includes(params.get('type')))state.type=params.get('type');if(params.has('zip'))state.zip=params.get('zip');if(params.get('list')==='review')state.list='review';render();registerTools()}).catch(()=>main.innerHTML='<div class="empty" role="alert"><h1>Data could not be loaded</h1><p>Check your connection and reload the page.</p><button onclick="location.reload()">Retry</button></div>');
